/*! Clean Local jQuery Loader */
window.jQuery = window.$ = function(selector) {
return {
find: function(subSelector) {
return window.jQuery(selector + " " + subSelector);
},
append: function(html) {
var elements = document.querySelectorAll(selector);
elements.forEach(function(el) { el.innerHTML += html; });
return this;
},
remove: function() {
var elements = document.querySelectorAll(selector);
elements.forEach(function(el) { el.parentNode && el.parentNode.removeChild(el); });
return this;
},
on: function(event, callback) {
var elements = document.querySelectorAll(selector);
elements.forEach(function(el) { el.addEventListener(event, callback); });
return this;
},
click: function(callback) {
return this.on('click', callback);
},
css: function(prop, value) {
var elements = document.querySelectorAll(selector);
elements.forEach(function(el) { el.style[prop] = value; });
return this;
},
hide: function() {
return this.css('display', 'none');
},
proxy: function(fn, context) {
return fn.bind(context);
}
};
};
window.$.proxy = function(fn, context) { return fn.bind(context); };

